window.products.push({"id":363849,"name":"WalterDrake White Expandable Magnetic Curtain Rod 17\" - 30.5\"","category":"homeandappliances","retail price":22.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/61UtkACusaL._AC_SL1500_.jpg","description":"Hanging curtains has never been easier! This extendable curtain rod adheres to both metal and wooden surfaces, without drilling or damaging the finish. The secret is in the two strong magnetic rod supports. Fasten each directly to metal surface or frames. For wooden surfaces, use the metal plates, with the peel and stick backing, to create an area for the magnets to adhere.","images":["https://m.media-amazon.com/images/I/61UtkACusaL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"EXPANDABLE CURTAINS","source_asin":"B0097FE1T0","category_path":"Home & Kitchen"},"sku":"BM-363849","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B0097FE1T0","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B0097FE1T0","price_pending":true,"merchant_ready":false});
